    tplKeys.forEach((m) => usedKeys.add(m.replace(/^\$t\(\s*['"]/, "").replace(/['"]$/, "")));
  }
  try {
    babelParser.parse(sfc.script.content, {
      sourceType: "module",
      plugins: ["optionalChaining", "objectRestSpread"],
    });
    console.log("script ok:", rel);
  } catch (e) {
    console.log("SCRIPT ERROR", rel, e.message);
    bad++;
  }
  const scriptKeys = sfc.script.content.match(/\$t\(\s*['"]([^'"]+)['"]/g) || [];
  scriptKeys.forEach((m) => usedKeys.add(m.replace(/^\$t\(\s*['"]/, "").replace(/['"]$/, "")));
}

function loadModule(rel) {
  const src = fs.readFileSync(path.join(root, rel), "utf8");
  const code = src.replace(/export\s+default/, "module.exports =");
  const mod = { exports: {} };
  new Function("module", "exports", code)(mod, mod.exports);
  return mod.exports;
}

const zh = loadModule("src/i18n/lang/zh-CN/product.js");
const en = loadModule("src/i18n/lang/en-US/product.js");

function flatten(obj, prefix, out) {
  out = out || {};
  Object.keys(obj).forEach((k) => {
    const v = obj[k];
    const key = prefix ? prefix + "." + k : k;
    if (v && typeof v === "object") flatten(v, key, out);
    else out[key] = v;
  });
  return out;
}
const fz = flatten(zh, "");
const fe = flatten(en, "");
const zk = Object.keys(fz).sort();
const ek = Object.keys(fe).sort();
console.log("\nzh keys:", zk.join(", "));
console.log("en keys:", ek.join(", "));
if (zk.join("|") !== ek.join("|")) {
  console.log("!! KEY STRUCTURE MISMATCH");
  bad++;
}

// 校验三个文件里用到的 key 是否存在（common.* 与 product.* 分别解析）
const loadNs = (loc, ns) => loadModule(`src/i18n/lang/${loc}/${ns}.js`);
const nsCache = {};
function resolveKey(loc, key) {
  const ns = key.split(".")[0];
  const cacheKey = loc + "/" + ns;
  if (!nsCache[cacheKey]) {
    try {
      nsCache[cacheKey] = flatten(loadNs(loc, ns), "");
    } catch (e) {
      nsCache[cacheKey] = null;
    }
  }
  const flat = nsCache[cacheKey];
  if (!flat) return undefined;
  return flat[key.split(".").slice(1).join(".")];
}
console.log("");
[...usedKeys].sort().forEach((k) => {
  const z = resolveKey("zh-CN", k);
  const e = resolveKey("en-US", k);
  const okMark = z !== undefined && e !== undefined ? "ok " : "!! ";
  if (okMark !== "ok ") bad++;
  console.log(`${okMark}${k}  zh=${JSON.stringify(z)}  en=${JSON.stringify(e)}`);
});

console.log(bad === 0 ? "\nALL CHECKS PASSED" : `\n${bad} PROBLEM(S)`);
"}

